// Telegram'dan gelen yeni mesajları komut olarak işler.
// Görev / harcama / not / fiyat listeleri önceki düğümlerde okundu; burada
// yalnızca bellekte güncellenir, dosyaya yazmayı sonraki dallar yapar.
const yanitHttp = $('Yeni Mesajları Getir').first().json || {};
const listeOku = (dugum, alan) => {
  const j = $(dugum).first().json || {};
  const d = (j.data && j.data[alan]) || [];
  return Array.isArray(d) ? d.map((x) => ({ ...x })) : [];
};
const gorevler = listeOku('Görevleri Çıkar (Bot)', 'gorevler');
const harcamalar = listeOku('Harcamaları Çıkar (Bot)', 'harcamalar');
const notlar = listeOku('Notları Çıkar (Bot)', 'notlar');
const urunler = listeOku('Fiyatları Çıkar (Bot)', 'urunler');
const offsetJson = $('Offseti Çıkar').first().json || {};
const eskiOffset = Number((offsetJson.data && offsetJson.data.offset) || 0);
const izinliChat = String($env.TELEGRAM_CHAT_ID || '').trim();

const updates = yanitHttp.ok && Array.isArray(yanitHttp.result) ? yanitHttp.result : [];
let yeniOffset = eskiOffset;
let gorevDegisti = false;
let harcamaDegisti = false;
let notDegisti = false;
const yanitlar = [];

const tl = (n) => Number(n).toLocaleString('tr-TR', { maximumFractionDigits: 2 }) + ' TL';
const simdiIso = () => new Date().toISOString();
const siradakiId = (liste) => liste.reduce((mx, x) => Math.max(mx, Number(x.id) || 0), 0) + 1;
const gunSaat = (d) => d.toLocaleString('tr-TR', { day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' });
const ayAnahtari = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');

const acikListe = () => {
  const acik = gorevler.filter((x) => x.durum !== 'tamam');
  if (acik.length === 0) return 'Açık görev yok. 🎉';
  return 'Açık görevler:\n' + acik.map((x) => '#' + x.id + ' ' + x.baslik + (x.not ? ' — ' + x.not : '')).join('\n');
};

const notListesi = () => {
  const acik = notlar.filter((n) => n && n.durum !== 'gonderildi');
  if (acik.length === 0) return 'Not ve bekleyen hatırlatma yok.';
  return '📝 Notlar:\n' + acik
    .map((n) => '#' + n.id + ' ' + n.metin + (n.hatirlat ? ' ⏰ ' + gunSaat(new Date(n.hatirlat)) : ''))
    .join('\n') + '\n\nSilmek için: /notsil <numara>';
};

// "149,90" · "1.250" · "1.234,56" · "89.5" → sayı
const sayiyaCevir = (ham) => {
  let t = String(ham).trim();
  const sonNokta = t.lastIndexOf('.');
  const sonVirgul = t.lastIndexOf(',');
  if (sonVirgul > sonNokta) t = t.replace(/\./g, '').replace(',', '.');
  else if (sonVirgul === -1 && /^\d{1,3}(\.\d{3})+$/.test(t)) t = t.replace(/\./g, '');
  else t = t.replace(/,/g, '');
  const n = Number(t);
  return Number.isFinite(n) ? n : null;
};

// "18:30" · "yarın 09:00" · "25.08 18:30" · "25.08.2026 18:30" · "30dk" · "2saat"
const zamanCoz = (ham) => {
  const s = String(ham).trim();
  const k = s.toLowerCase();
  let m;
  if ((m = k.match(/^(\d+)\s*(dk|dakika)\b\s*/))) {
    return { ne: new Date(Date.now() + Number(m[1]) * 60000), kalan: s.slice(m[0].length).trim() };
  }
  if ((m = k.match(/^(\d+)\s*(sa|saat)\b\s*/))) {
    return { ne: new Date(Date.now() + Number(m[1]) * 3600000), kalan: s.slice(m[0].length).trim() };
  }
  if ((m = k.match(/^(\d{1,2})[.\/](\d{1,2})(?:[.\/](\d{2,4}))?\s+(\d{1,2})[:.](\d{2})\s*/))) {
    const yil = m[3] ? (m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3])) : new Date().getFullYear();
    return { ne: new Date(yil, Number(m[2]) - 1, Number(m[1]), Number(m[4]), Number(m[5]), 0, 0), kalan: s.slice(m[0].length).trim() };
  }
  if ((m = k.match(/^(yarın|yarin)\s*(?:(\d{1,2})[:.](\d{2}))?\s*/))) {
    const d = new Date();
    d.setDate(d.getDate() + 1);
    d.setHours(m[2] ? Number(m[2]) : 9, m[3] ? Number(m[3]) : 0, 0, 0);
    return { ne: d, kalan: s.slice(m[0].length).trim() };
  }
  if ((m = k.match(/^(\d{1,2})[:.](\d{2})\s*/))) {
    const d = new Date();
    d.setHours(Number(m[1]), Number(m[2]), 0, 0);
    if (d.getTime() <= Date.now()) d.setDate(d.getDate() + 1); // saat geçtiyse yarın
    return { ne: d, kalan: s.slice(m[0].length).trim() };
  }
  return null;
};

const yardimMetni = (chatId) => [
  'Merhaba! Komutlar:',
  '',
  '📋 Görev',
  '• Düz metin yaz → görev olarak eklenir',
  '• /liste · /tamamla 3 · /sil 3',
  '',
  '💸 Harcama',
  '• /harcama 149,90 market → kaydeder',
  '• /harcamalar → bu ayın dökümü',
  '',
  '🏷 Fiyat',
  '• /fiyat → takip listesi ve son fiyatlar',
  '',
  '📝 Not ve hatırlatma (workflow 09 aktif olmalı)',
  '• /not Kitap önerisi: ...',
  '• /hatirlat 18:30 çamaşırı as',
  '• /hatirlat 2saat ilacı al · /hatirlat yarın 09:00 ara',
  '• /notlar · /notsil 3',
  '',
  '📌 /bugun → görev + hatırlatma + harcama özeti',
  '',
  'Sohbet ID: ' + chatId,
  'Sabah özeti ve güvenlik için .env dosyasına TELEGRAM_CHAT_ID=' + chatId + ' yazıp n8n\'i yeniden başlatın.',
].join('\n');

for (const u of updates) {
  if (typeof u.update_id === 'number' && u.update_id >= yeniOffset) yeniOffset = u.update_id + 1;
  const m = u.message;
  if (!m || !m.chat) continue;
  const chatId = m.chat.id;
  if (izinliChat && String(chatId) !== izinliChat) continue; // yabancı sohbetleri yok say
  const metin = String(m.text || '').trim();
  if (!metin) {
    yanitlar.push({ chat_id: chatId, text: 'Metin mesajı bekliyorum. Komutlar için /yardim yazın.' });
    continue;
  }
  const ilkKelime = metin.split(/\s+/)[0];
  const arg = metin.slice(ilkKelime.length).trim();
  const komut = ilkKelime.toLowerCase().replace(/^\//, '').replace(/@\w+$/, '');
  const komutMu = ilkKelime.startsWith('/');
  let text = '';

  if (komut === 'start' || komut === 'yardim' || komut === 'yardım') {
    text = yardimMetni(chatId);
  } else if (komut === 'liste' || komut === 'gorevler' || komut === 'görevler') {
    text = acikListe();
  } else if ((komut === 'tamamla' || komut === 'sil') && /^#?\d+/.test(arg)) {
    const id = Number(arg.match(/^#?(\d+)/)[1]);
    const gorev = gorevler.find((x) => Number(x.id) === id);
    if (!gorev) {
      text = '#' + id + ' bulunamadı. /liste ile kontrol edin.';
    } else if (komut === 'tamamla') {
      gorev.durum = 'tamam';
      gorev.tamamlanma = simdiIso();
      gorevDegisti = true;
      text = '✅ Tamamlandı: #' + id + ' ' + gorev.baslik + '\n' + acikListe();
    } else {
      gorevler.splice(gorevler.indexOf(gorev), 1);
      gorevDegisti = true;
      text = '🗑 Silindi: #' + id + ' ' + gorev.baslik;
    }
  } else if (komut === 'harcama') {
    const h = arg.match(/^([0-9.,]+)\s*(?:tl|₺|try)?\s*(.*)$/i);
    const tutar = h ? sayiyaCevir(h[1]) : null;
    if (!tutar || tutar <= 0) {
      text = 'Kullanım: /harcama 149,90 market\n(önce tutar, sonra açıklama)';
    } else {
      const aciklama = (h[2] || '').trim() || 'Açıklama yok';
      const simdi = simdiIso();
      harcamalar.push({
        anahtar: 'telegram|' + simdi,
        tarih: simdi,
        kimden: 'Elle (Telegram)',
        konu: aciklama,
        tutar,
        paraBirimi: 'TL',
        eklenme: simdi,
      });
      harcamaDegisti = true;
      const ay = ayAnahtari(new Date());
      const ayToplam = harcamalar
        .filter((x) => String(x.tarih || '').startsWith(ay) && typeof x.tutar === 'number')
        .reduce((t, x) => t + x.tutar, 0);
      text = '💸 Kaydedildi: ' + tl(tutar) + ' — ' + aciklama + '\nBu ay toplam: ' + tl(ayToplam);
    }
  } else if (komut === 'harcamalar') {
    const simdi = new Date();
    const ay = ayAnahtari(simdi);
    const adAy = simdi.toLocaleDateString('tr-TR', { month: 'long', year: 'numeric' });
    const ayinkiler = harcamalar.filter((x) => String(x.tarih || '').startsWith(ay));
    const tutarlilar = ayinkiler.filter((x) => typeof x.tutar === 'number');
    if (ayinkiler.length === 0) {
      text = '💳 ' + adAy + ': kayıt yok.';
    } else {
      const gruplar = new Map();
      for (const x of tutarlilar) {
        const k = x.kimden || 'Bilinmeyen';
        gruplar.set(k, (gruplar.get(k) || 0) + x.tutar);
      }
      const satirlar = [...gruplar.entries()]
        .sort((a, b) => b[1] - a[1])
        .slice(0, 8)
        .map(([k, v]) => '• ' + k + ': ' + tl(v));
      const toplam = tutarlilar.reduce((t, x) => t + x.tutar, 0);
      text = '💳 ' + adAy + '\nToplam: ' + tl(toplam) + ' (' + ayinkiler.length + ' kayıt)\n' + satirlar.join('\n');
    }
  } else if (komut === 'fiyat' || komut === 'fiyatlar') {
    if (urunler.length === 0) {
      text = 'Takip listesi boş. local-files/fiyat-takibi.json dosyasına ürün ekleyin.';
    } else {
      text = '🏷 Fiyat takibi:\n' + urunler
        .map((u2) => {
          const fiyat = typeof u2.sonFiyat === 'number' ? tl(u2.sonFiyat) : 'okunamadı';
          const hedef = typeof u2.esik === 'number' ? ' (hedef ' + tl(u2.esik) + ')' : '';
          const isaret = typeof u2.sonFiyat === 'number' && typeof u2.esik === 'number' && u2.sonFiyat <= u2.esik ? '🎯 ' : '• ';
          return isaret + (u2.ad || 'Ürün') + ': ' + fiyat + hedef + (u2.sonHata ? ' ⚠️' : '');
        })
        .join('\n');
    }
  } else if (komut === 'not') {
    if (!arg) {
      text = 'Kullanım: /not markete uğramayı unutma';
    } else {
      const id = siradakiId(notlar);
      notlar.push({ id, metin: arg, hatirlat: null, durum: 'acik', olusturulma: simdiIso() });
      notDegisti = true;
      text = '📝 Not eklendi: #' + id + ' ' + arg;
    }
  } else if (komut === 'hatirlat' || komut === 'hatırlat') {
    const c = zamanCoz(arg);
    if (!c || isNaN(c.ne.getTime()) || !c.kalan) {
      text = [
        'Kullanım: /hatirlat <zaman> <ne>',
        '• /hatirlat 18:30 çamaşırı as',
        '• /hatirlat 30dk çayı demle',
        '• /hatirlat 2saat ilacı al',
        '• /hatirlat yarın 09:00 doktoru ara',
        '• /hatirlat 25.08 14:00 fatura öde',
      ].join('\n');
    } else {
      const id = siradakiId(notlar);
      notlar.push({ id, metin: c.kalan, hatirlat: c.ne.toISOString(), durum: 'acik', olusturulma: simdiIso() });
      notDegisti = true;
      text = '⏰ Hatırlatma kuruldu: #' + id + ' ' + c.kalan + '\n' + gunSaat(c.ne) + ' geldiğinde yazacağım.';
    }
  } else if (komut === 'notlar') {
    text = notListesi();
  } else if (komut === 'notsil' && /^#?\d+/.test(arg)) {
    const id = Number(arg.match(/^#?(\d+)/)[1]);
    const n2 = notlar.find((x) => Number(x.id) === id);
    if (!n2) {
      text = '#' + id + ' bulunamadı. /notlar ile kontrol edin.';
    } else {
      notlar.splice(notlar.indexOf(n2), 1);
      notDegisti = true;
      text = '🗑 Not silindi: #' + id + ' ' + n2.metin;
    }
  } else if (komut === 'bugun' || komut === 'bugün') {
    const bas = new Date();
    bas.setHours(0, 0, 0, 0);
    const bit = new Date(bas);
    bit.setDate(bit.getDate() + 1);
    const zaman = (s) => new Date(s).getTime();
    const acik = gorevler.filter((x) => x.durum !== 'tamam');
    const bugunkuNotlar = notlar.filter((n2) => n2.hatirlat && zaman(n2.hatirlat) >= bas.getTime() && zaman(n2.hatirlat) < bit.getTime());
    const bugunkuHarcama = harcamalar.filter((x) => typeof x.tutar === 'number' && zaman(x.tarih) >= bas.getTime());
    const bolumler = ['📌 ' + bas.toLocaleDateString('tr-TR', { weekday: 'long', day: 'numeric', month: 'long' })];
    bolumler.push(acik.length
      ? '\n📋 Açık görev (' + acik.length + '):\n' + acik.slice(0, 8).map((x) => '#' + x.id + ' ' + x.baslik).join('\n')
      : '\n📋 Açık görev yok. 🎉');
    if (bugunkuNotlar.length) {
      bolumler.push('\n⏰ Bugünün hatırlatmaları:\n' + bugunkuNotlar
        .sort((a, b) => zaman(a.hatirlat) - zaman(b.hatirlat))
        .map((n2) => new Date(n2.hatirlat).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }) + ' ' + n2.metin + (n2.durum === 'gonderildi' ? ' ✓' : ''))
        .join('\n'));
    }
    if (bugunkuHarcama.length) {
      const toplam = bugunkuHarcama.reduce((t, x) => t + x.tutar, 0);
      bolumler.push('\n💸 Bugünkü harcama: ' + tl(toplam) + ' (' + bugunkuHarcama.length + ' kayıt)');
    }
    text = bolumler.join('\n');
  } else if (komutMu) {
    text = 'Bilinmeyen komut: ' + ilkKelime + '\nKomutlar için /yardim yazın.';
  } else {
    const id = siradakiId(gorevler);
    gorevler.push({ id, baslik: metin, not: '', durum: 'acik', olusturulma: simdiIso() });
    gorevDegisti = true;
    text = '➕ Eklendi: #' + id + ' ' + metin;
  }

  yanitlar.push({ chat_id: chatId, text: text.slice(0, 3900) });
}

return [{
  json: {
    gorevler,
    harcamalar,
    notlar,
    yanitlar,
    yeniOffset,
    gorevYazilsin: gorevDegisti,
    harcamaYazilsin: harcamaDegisti,
    notYazilsin: notDegisti,
    offsetYazilsin: yeniOffset !== eskiOffset,
  },
}];

// Token veya sohbet ID .env dosyasında yoksa sabah özeti sessizce atlanır.
if (!String($env.TELEGRAM_BOT_TOKEN || '').trim() || !String($env.TELEGRAM_CHAT_ID || '').trim()) return [];
return [{ json: {} }];

// Açık görevlerden sabah özet mesajı hazırlar.
const okunan = $input.first().json;
const g0 = (okunan.data && okunan.data.gorevler) || [];
const gorevler = Array.isArray(g0) ? g0 : [];
const acik = gorevler.filter((x) => x && x.durum !== 'tamam');
const bugun = new Date().toLocaleDateString('tr-TR', { weekday: 'long', day: 'numeric', month: 'long' });
let text;
if (acik.length === 0) {
  text = '📋 Günaydın! ' + bugun + '\nAçık görev yok. 🎉';
} else {
  text = '📋 Günaydın! ' + bugun + '\nAçık görevler (' + acik.length + '):\n' +
    acik.map((x) => '#' + x.id + ' ' + x.baslik + (x.not ? ' — ' + x.not : '')).join('\n') +
    '\n\nTamamlamak için: /tamamla <numara>';
}
return [{ json: { chat_id: String($env.TELEGRAM_CHAT_ID).trim(), text } }];
